import { createSelector } from "@reduxjs/toolkit";
import { exercisesAdapter } from "./exercisesSlice";

// Basic selectors generated by the entity adapter
export const {
  selectAll: selectAllExercises, // sorted by createdAt (oldest first)
  selectById: selectExerciseById,
} = exercisesAdapter.getSelectors((state) => state.exercises);

export const selectExercisesListState = (state) => state.exercises.list;

export const selectExerciseDetailsState = (state, id) => state.exercises.details[id];

export const selectMutationState = (state, key) => state.exercises.mutations[key];

export const selectVisibleExercises = createSelector(
  [
    selectAllExercises,
    (state, status) => status,
    (state, status, order) => order,
  ],
  (exercises, status, order) => {
    // Always a new array (reselect warns if a selector returns its input unchanged)
    const filtered =
      status === "All" ? [...exercises] : exercises.filter((exercise) => exercise.status === status);
    return order === "desc" ? filtered.reverse() : filtered;
  }
);

export const selectExerciseStats = createSelector([selectAllExercises], (exercises) => ({
  total: exercises.length,
  planned: exercises.filter((e) => e.status === "Planned").length,
  inProgress: exercises.filter((e) => e.status === "In Progress").length,
  completed: exercises.filter((e) => e.status === "Completed").length,
}));
